public class JacksonAnnotationIntrospector_findObjectReferenceInfo_TriageGen2Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    /**
     * Test case where the annotation is NOT present.
     * Expected: Return the original objectIdInfo unchanged.
     */
    @Test
    public void testFindObjectReferenceInfo_NoAnnotation() {
        Annotated mockAnn = mock(Annotated.class);
        ObjectIdInfo mockObjectIdInfo = mock(ObjectIdInfo.class);

        // Since _findAnnotation is protected and called internally, 
        // we rely on the fact that mockAnn will not have the JsonIdentityReference annotation.
        // We need to simulate the behavior of _findAnnotation returning null.
        // Because we cannot easily mock the protected _findAnnotation method in a real instance 
        // without a spy, we use a spy to control the internal call.
        JacksonAnnotationIntrospector spyIntrospector = spy(introspector);
        doReturn(null).when(spyIntrospector)._findAnnotation(eq(mockAnn), eq(JsonIdentityReference.class));

        ObjectIdInfo result = spyIntrospector.findObjectReferenceInfo(mockAnn, mockObjectIdInfo);

        assertSame("Should return the original objectIdInfo when no annotation is found", 
            mockObjectIdInfo, result);
    }

    /**
     * Test case where the annotation IS present and alwaysAsId is true.
     * Expected: Return a new ObjectIdInfo with alwaysAsId(true) called.
     */
    @Test
    public void testFindObjectReferenceInfo_WithAnnotation_AlwaysAsIdTrue() {
        Annotated mockAnn = mock(Annotated.class);
        ObjectIdInfo mockObjectIdInfo = mock(ObjectIdInfo.class);
        JsonIdentityReference mockRef = mock(JsonIdentityReference.class);
        ObjectIdInfo updatedObjectIdInfo = mock(ObjectIdInfo.class);

        JacksonAnnotationIntrospector spyIntrospector = spy(introspector);

        // Mock the annotation finding logic
        doReturn(mockRef).when(spyIntrospector)._findAnnotation(eq(mockAnn), eq(JsonIdentityReference.class));
        // Mock the annotation property
        when(mockRef.alwaysAsId()).thenReturn(true);
        // Mock the immutable withAlwaysAsId method
        when(mockObjectIdInfo.withAlwaysAsId(true)).thenReturn(updatedObjectIdInfo);

        ObjectIdInfo result = spyIntrospector.findObjectReferenceInfo(mockAnn, mockObjectIdInfo);

        assertNotNull(result);
        assertEquals("Should return the updated ObjectIdInfo", updatedObjectIdInfo, result);
        verify(mockObjectIdInfo).withAlwaysAsId(true);
    }

    /**
     * Test case where the annotation IS present and alwaysAsId is false.
     * Expected: Return a new ObjectIdInfo with alwaysAsId(false) called.
     */
    @Test
    public void testFindObjectReferenceInfo_WithAnnotation_AlwaysAsIdFalse() {
        Annotated mockAnn = mock(Annotated.class);
        ObjectIdInfo mockObjectIdInfo = mock(ObjectIdInfo.class);
        JsonIdentityReference mockRef = mock(JsonIdentityReference.class);
        ObjectIdInfo updatedObjectIdInfo = mock(ObjectIdInfo.class);

        JacksonAnnotationIntrospector spyIntrospector = spy(introspector);

        doReturn(mockRef).when(spyIntrospector)._findAnnotation(eq(mockAnn), eq(JsonIdentityReference.class));
        when(mockRef.alwaysAsId()).thenReturn(false);
        when(mockObjectIdInfo.withAlwaysAsId(false)).thenReturn(updatedObjectIdInfo);

        ObjectIdInfo result = spyIntrospector.findObjectReferenceInfo(mockAnn, mockObjectIdInfo);

        assertNotNull(result);
        assertEquals("Should return the updated ObjectIdInfo", updatedObjectIdInfo, result);
        verify(mockObjectIdInfo).withAlwaysAsId(false);
    }
}
